import fitz, os, re, sys

def get_patterns():
    # Basic regex patterns for identifying info
    patterns = [
        r"[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}",  # email addresses
        r"arXiv:\s*\d{4}\.\d{4,5}",                     # arXiv IDs
        r"10\\.[0-9]{4,9}/[-._;()/:A-Z0-9]+",            # DOIs (case‑insensitive)
        r"ICML", r"NeurIPS", r"CVPR", r"ECCV", r"ICLR", r"AAAI", r"ACL", r"EMNLP", r"KDD", r"SIGIR"
    ]
    return [re.compile(p, re.IGNORECASE) for p in patterns]

def find_references_page(doc):
    for i, page in enumerate(doc):
        txt = page.get_text().lower()
        if "references" in txt:
            return i
    return None

def redact_page(page, regexes):
    txt = page.get_text()
    for regex in regexes:
        for match in regex.finditer(txt):
            match_str = match.group(0)
            # search_for may return multiple rectangles for the same string; redact all
            for rect in page.search_for(match_str, hit_max=16):
                page.add_redact_annot(rect, fill=(0, 0, 0))
    page.apply_redactions()

def redact_file(input_path, output_path, regexes):
    doc = fitz.open(input_path)
    ref_page = find_references_page(doc)
    for i, page in enumerate(doc):
        if ref_page is not None and i >= ref_page:
            continue  # skip references and later pages
        redact_page(page, regexes)
    os.makedirs(os.path.dirname(output_path), exist_ok=True)
    doc.save(output_path, garbage=4, deflate=True)
    doc.close()

def verify(original_path, redacted_path):
    orig = fitz.open(original_path)
    redc = fitz.open(redacted_path)
    orig_len = sum(len(p.get_text()) for p in orig)
    redc_len = sum(len(p.get_text()) for p in redc)
    if len(orig) != len(redc):
        print(f"⚠️ Page count changed: {len(orig)} -> {len(redc)}")
    retain = redc_len / orig_len if orig_len else 0
    print(f"Retention: {retain:.1%} (orig {orig_len} chars, redacted {redc_len} chars)")
    if retain < 0.7:
        print("⚠️ Too much content removed; possible over‑redaction.")
    else:
        print("✅ Verification passed")
    orig.close(); redc.close()

def main():
    if len(sys.argv) < 2:
        print("Usage: python redact_papers.py <pdf1> [<pdf2> ...]")
        sys.exit(1)
    regexes = get_patterns()
    for in_path in sys.argv[1:]:
        base = os.path.basename(in_path)
        out_path = os.path.join('/root/redacted', base)
        print(f"Redacting {in_path} -> {out_path}")
        redact_file(in_path, out_path, regexes)
        verify(in_path, out_path)

if __name__ == "__main__":
    main()
